# openEMS model generated by OpenBoard (RF PCB). Requires openEMS + CSXCAD Python bindings.
import os, numpy as np
from CSXCAD import ContinuousStructure
from openEMS import openEMS
from openEMS.physical_constants import C0
unit = 1e-3; f_max = 10e9; f0 = f_max / 2; fc = f_max / 2
FDTD = openEMS(NrTS=60000, EndCriteria=1e-4)
FDTD.SetGaussExcite(f0, fc)
FDTD.SetBoundaryCond(['PML_8'] * 6)
CSX = ContinuousStructure()
FDTD.SetCSX(CSX)
mesh = CSX.GetGrid(); mesh.SetDeltaUnit(unit)
metal = CSX.AddMetal("copper")
sub0 = CSX.AddMaterial("diel0", epsilon=4.4, kappa=2.4478e-2)
sub0.AddBox([0, 0, 0.035], [227.6, 179.3, 1.565], priority=0)
metal.AddLinPoly(points=np.array([[107.8, 119.8, 119.8, 115.8, 115.8, 224.6, 224.6, 111.8, 111.8, 107.8], [176.3, 176.3, 164.7, 86, 64.5, 85, 3, 23.5, 86, 164.7]]), norm_dir='z', elevation=0, length=0.035, priority=10)  # 0
metal.AddLinPoly(points=np.array([[112.395, 115.205, 115.205, 115.8, 115.8, 3, 3, 111.8, 111.8, 112.395], [174.1, 174.1, 164.7, 86, 23.5, 3, 85, 64.5, 86, 164.7]]), norm_dir='z', elevation=1.565, length=0.035, priority=10)  # 1
metal.AddLinPoly(points=np.array([[116.205, 119.8, 119.8, 116.205], [176.3, 176.3, 169.7, 169.7]]), norm_dir='z', elevation=1.565, length=0.035, priority=10)  # 2
metal.AddLinPoly(points=np.array([[107.8, 111.395, 111.395, 107.8], [176.3, 176.3, 169.7, 169.7]]), norm_dir='z', elevation=1.565, length=0.035, priority=10)  # 3
metal.AddLinPoly(points=np.array([[112.2, 115.4, 115.4, 112.2], [173.465, 173.465, 174.735, 174.735]]), norm_dir='z', elevation=1.565, length=0.035, priority=10)  # 4
metal.AddLinPoly(points=np.array([[114.775, 118.475, 118.475, 114.775], [173.675, 173.675, 175.025, 175.025]]), norm_dir='z', elevation=1.565, length=0.035, priority=10)  # 5
metal.AddLinPoly(points=np.array([[114.775, 118.475, 118.475, 114.775], [173.675, 173.675, 175.025, 175.025]]), norm_dir='z', elevation=1.565, length=0.035, priority=10)  # 6
metal.AddLinPoly(points=np.array([[109.125, 112.825, 112.825, 109.125], [173.675, 173.675, 175.025, 175.025]]), norm_dir='z', elevation=1.565, length=0.035, priority=10)  # 7
metal.AddLinPoly(points=np.array([[109.125, 112.825, 112.825, 109.125], [173.675, 173.675, 175.025, 175.025]]), norm_dir='z', elevation=1.565, length=0.035, priority=10)  # 8
metal.AddLinPoly(points=np.array([[114.775, 118.475, 118.475, 114.775], [173.675, 173.675, 175.025, 175.025]]), norm_dir='z', elevation=0, length=0.035, priority=10)  # 9
metal.AddLinPoly(points=np.array([[109.125, 112.825, 112.825, 109.125], [173.675, 173.675, 175.025, 175.025]]), norm_dir='z', elevation=0, length=0.035, priority=10)  # 10
port1 = FDTD.AddLumpedPort(1, 50, [113.165, 173.465, 0.035], [114.435, 174.735, 1.565], 'z', excite=1, priority=20)  # J1-1
mesh.AddLine('x', [0, 227.6]); mesh.AddLine('y', [0, 179.3]); mesh.AddLine('z', [-3, 4.6])
mesh.AddLine('z', [1.565, 1.6, 0, 0.035])
for d in 'xyz':
    mesh.SmoothMeshLines(d, C0 / f_max / unit / 20, 1.4)
sim = os.path.join(os.getcwd(), 'openboard_rf')
FDTD.Run(sim, cleanup=True)
f = np.linspace(max(1e6, f0 - fc), f0 + fc, 401)
for prt in [p for p in [globals().get("port%d" % i) for i in range(1, 9)] if p is not None]: prt.CalcPort(sim, f)
s11 = port1.uf_ref / port1.uf_inc
out = ["# Hz S RI R 50"] + ["%g %g %g" % (fi, s.real, s.imag) for fi, s in zip(f, s11)]
if 'port2' in globals(): s21 = port2.uf_ref / port1.uf_inc; out = ["# Hz S RI R 50"] + ["%g %g %g %g %g %g %g %g %g" % (fi, a.real, a.imag, b.real, b.imag, b.real, b.imag, a.real, a.imag) for fi, a, b in zip(f, s11, s21)]
open('openboard_rf.s%dp' % (2 if 'port2' in globals() else 1), 'w').write('\n'.join(out))
